/bin/bash -lc "npm run build && node --input-type=module <<'JS'
import { chromium, expect } from '@playwright/test';
import { spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const folder = await mkdtemp(join(tmpdir(), 'chapter-browser-'));
const filename = join(folder, 'books.json');
await writeFile(filename, '[]');
let child;
async function start() {
  child = spawn(process.execPath, ['server/index.js','--production'], {env:{...process.env,PORT:'4173',BOOKS_FILE:filename},stdio:['ignore','pipe','pipe']});
  await new Promise((resolve,reject)=>{child.stdout.once('data',resolve);child.once('error',reject);child.stderr.on('data',data=>console.log(data.toString()));});
}
async function stop() { await new Promise(resolve=>{child.once('exit',resolve);child.kill();}); }
const browser = await chromium.launch({headless:true});
try {
  await start();
  const context = await browser.newContext({viewport:{width:1440,height:1000},permissions:['clipboard-read','clipboard-write']});
  const page = await context.newPage();
  const errors=[]; page.on('pageerror',error=>errors.push(error.message));
  await page.goto('http://localhost:4173');
  await expect(page.getByRole('heading',{name:'Every reading life starts with one book.'})).toBeVisible();
  await page.getByRole('button',{name:'Add a book',exact:true}).first().click();
  await page.getByLabel('Book title').fill('A Room of One’s Own');
  await page.getByLabel('Author',{exact:true}).fill('Virginia Woolf');
  await page.getByLabel('Your notes').fill('A first thought.');
  await page.getByRole('button',{name:'Terracotta cover'}).click();
  await page.screenshot({path:'/tmp/chapter-add.png',fullPage:true});
  await page.getByRole('button',{name:'Add to my library'}).click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await page.getByRole('link',{name:'A Room of One’s Own',exact:true}).click();
  await expect(page.getByRole('heading',{name:'A Room of One’s Own',exact:true})).toBeVisible();
  const bookUrl=page.url();
  await page.getByRole('textbox',{name:'My notes',exact:true}).fill('A thought worth keeping.\\n\\nAnd another chapter.');
  await page.getByRole('button',{name:'Save notes'}).click();
  await expect(page.getByText('All thoughts saved')).toBeVisible();
  await page.getByRole('button',{name:'Share book'}).click();
  expect(await page.evaluate(()=>navigator.clipboard.readText())).toBe(bookUrl);
  await page.getByRole('button',{name:'Mark as finished',exact:true}).click();
  await expect(page.getByRole('button',{name:'Read it again'})).toBeVisible();
  await page.screenshot({path:'/tmp/chapter-detail.png',fullPage:true});
  await stop(); await start();
  await page.goto(bookUrl);
  await expect(page.getByRole('textbox',{name:'My notes',exact:true})).toHaveValue('A thought worth keeping.\\n\\nAnd another chapter.');
  await expect(page.getByRole('button',{name:'Read it again'})).toBeVisible();
  await page.getByRole('link',{name:'Back to my library'}).click();
  await page.getByRole('button',{name:/"'^Finished/}).click();
  await expect(page.locator('"'.finished-card')).toHaveCount(1);
  await page.getByRole('textbox',{name:'Search books'}).fill('not a matching book');
  await expect(page.getByRole('heading',{name:'No books on this shelf… yet.'})).toBeVisible();
  await page.getByRole('button',{name:'Clear search',exact:true}).first().click();
  await expect(page.locator('.finished-card')).toHaveCount(1);
  await page.getByRole('combobox',{name:'Sort books'}).selectOption('author');
  await page.getByRole('link',{name:'A Room of One’s Own',exact:true}).click();
  await page.getByRole('button',{name:'Read it again'}).click();
  await expect(page.getByRole('button',{name:'Mark as finished',exact:true})).toBeVisible();
  await page.getByRole('link',{name:'Back to my library'}).click();
  await page.getByRole('button',{name:'Mark as finished',exact:true}).click();
  await expect(page.locator('.finished-card')).toHaveCount(1);
  await page.setViewportSize({width:390,height:844});
  expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);
  await page.getByRole('button',{name:'Add a book',exact:true}).first().click();
  await expect(page.getByRole('dialog')).toBeVisible();
  expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);
  await page.keyboard.press('Escape');
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await page.getByRole('link',{name:'A Room of One’s Own',exact:true}).click();
  await page.getByRole('button',{name:'Remove from library'}).click();
  await page.getByRole('button',{name:'Remove book',exact:true}).click();
  await expect(page.getByRole('heading',{name:'Every reading life starts with one book.'})).toBeVisible();
  await page.goto(bookUrl);
  await expect(page.getByRole('heading',{name:'This chapter is missing.'})).toBeVisible();
  expect(errors).toEqual([]);
  console.log('PASS: add form, color selection, detail navigation, notes, clipboard sharing, status changes, production restart persistence, direct URLs, filters, search, sort, mobile layout, modal keyboard close, removal, and missing-book state. No browser errors.');
} finally { await browser.close(); if (child && child.exitCode===null) await stop(); await rm(folder,{recursive:true,force:true}); }
JS"
